// expectDelim reads the next token and asserts it is the given delimiter.
func expectDelim(dec *json.Decoder, want json.Delim) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	d, ok := tok.(json.Delim)
	if !ok || d != want {
		return fmt.Errorf("frpcodec: expected %q, got %v", want, tok)
	}
	return nil
}

// readKey reads the next token and asserts it is a string object key.
func readKey(dec *json.Decoder) (string, error) {
	tok, err := dec.Token()
	if err != nil {
		return "", err
	}
	key, ok := tok.(string)
	if !ok {
		return "", fmt.Errorf("frpcodec: expected string key, got %v", tok)
	}
	return key, nil
}
